// Получить ключи с остатком менее 50 за 24 часа
async function getEligibleKeys() {
  try {
    const since = new Date(Date.now() - 24 * 60 * 60 * 1000).toISOString();

    console.log('📊 Получаем usage за период:', since);
    const usageRes = await axios.get(
      `${SUPABASE_URL}/rest/v1/api_usage?select=key_id&used_at=gte.${since}`,
      { headers }
    );

    console.log(`📊 Найдено записей usage: ${usageRes.data?.length || 0}`);

    const usageCount = {};
    for (const row of usageRes.data || []) {
      usageCount[row.key_id] = (usageCount[row.key_id] || 0) + 1;
    }

    const keysRes = await axios.get(
      `${SUPABASE_URL}/rest/v1/API-keys%20OpenRouter?application=eq.Обработка%20писем`,
      { headers }
    );

    console.log(`📊 Найдено ключей: ${keysRes.data?.length || 0}`);

    const eligible = (keysRes.data || []).filter(k => (usageCount[k.id] || 0) < 50 && k.API);
    eligible.sort((a, b) => (usageCount[a.id] || 0) - (usageCount[b.id] || 0));

    console.log(`✅ Доступных ключей: ${eligible.length}`);
    return eligible;
  } catch (error) {
    console.error('❌ Ошибка получения ключей:', error.message);
    return [];
  }
}

// Извлечь JSON из ответа
function extractJsonFromResponse(str) {
  if (!str) return null;

  const jsonRegex = /```json\s*([\s\S]*?)```/i;
  const match = str.match(jsonRegex);
  if (match && match[1]) return match[1].trim();

  const objectRegex = /{[\s\S]*}/;
  const objectMatch = str.match(objectRegex);
  if (objectMatch) return objectMatch[0].trim();

  const arrayRegex = /\[[\s\S]*\]/;
  const arrayMatch = str.match(arrayRegex);
  if (arrayMatch) return arrayMatch[0].trim();

  return null;
}

// Вызов LLM
async function callLLM(apiKey, model, prompt) {
  const startTime = Date.now();
  let responseTime = null;
  let rawResponse = null;

  try {
    console.log(`🤖 Вызов LLM с моделью ${model}...`);
    const response = await axios.post(
      LLM_ENDPOINT,
      {
        model: model,
        messages: [{ role: 'user', content: prompt }],
      },
      {
        headers: {
          'Authorization': `Bearer ${apiKey}`,
          'Content-Type': 'application/json',
        },
        timeout: 60000
      }
    );

    responseTime = Date.now() - startTime;
    rawResponse = response.data?.choices?.[0]?.message?.content;

    console.log(`🤖 Ответ получен за ${responseTime}ms`);

    if (!rawResponse) {
      return {
        success: false,
        error: 'Пустой ответ от LLM',
        responseTime,
        rawResponse
      };
    }

    const cleaned = extractJsonFromResponse(rawResponse);
    if (!cleaned) {
      return {
        success: false,
        error: 'Не найден JSON в ответе',
        responseTime,
        rawResponse
      };
    }

    try {
      const parsed = JSON.parse(cleaned);
      return {
        success: true,
        data: parsed,
        responseTime,
        rawResponse
      };
    } catch (parseError) {
      return {
        success: false,
        error: `Ошибка парсинга JSON: ${parseError.message}`,
        responseTime,
        rawResponse
      };
    }

  } catch (error) {
    responseTime = Date.now() - startTime;
    let errorMessage;

    if (error.response?.data) {
      errorMessage = JSON.stringify(error.response.data);
      console.error('❌ Ошибка API OpenRouter:', error.response.data);
    } else {
      errorMessage = error.message;
      console.error('❌ Ошибка вызова LLM:', error.message);
    }

    return {
      success: false,
      error: errorMessage,
      responseTime,
      rawResponse: error.response?.data
    };
  }
}

