function formatDateTimeInMoscow(date) {
  const optionsDate = {
    timeZone: 'Europe/Moscow',
    day: '2-digit',
    month: '2-digit',
    year: 'numeric',
  };

  const optionsTime = {
    timeZone: 'Europe/Moscow',
    hour: '2-digit',
    minute: '2-digit',
