        'cp866': /ðƒð©ð▓ðÁÐé|ð┤ð¥ð▒ÐÇÐïð╣|Ðüð┐ð░Ðüð©ð▒ð¥/
    };

    for (const [encoding, pattern] of Object.entries(patterns)) {
